// EMA seeds are simple averages; MACD uses only the supplied closed candles.
function emaSeries(values,period){const out=Array(values.length).fill(null);if(values.length<period)return out;let e=values.slice(0,period).reduce((a,b)=>a+b,0)/period;out[period-1]=e;const k=2/(period+1);for(let i=period;i<values.length;i++){e+=(values[i]-e)*k;out[i]=e;}return out;}
export function macdFeatures(candles){const closes=candles.map(c=>c.close),empty={macdLine:null,macdSignal:null,macdHistogram:null,macdHistogramChange1:null};if(closes.length<34)return empty;const fast=emaSeries(closes,12),slow=emaSeries(closes,26),lines=closes.slice(25).map((_,i)=>fast[i+25]-slow[i+25]),signals=emaSeries(lines,9),i=lines.length-1,line=lines[i],signal=signals[i],hist=line-signal,previous=i>0&&signals[i-1]!==null?lines[i-1]-signals[i-1]:null;return {macdLine:line,macdSignal:signal,macdHistogram:hist,macdHistogramChange1:previous===null?null:hist-previous};}
